import SwiftUI
struct ResultsView:View{let plan:ActivityPlan;@Environment(AppState.self)private var app;@Environment(\.dismiss)private var dismiss;@State private var model=AnalysisViewModel();@State private var selected:Alternative?;@State private var keepOriginal=true;@State private var details=false
 var body:some View{Group{switch model.state{case .idle,.loading:ProgressView("Checking forecast conditions…");case .failed(let m):ContentUnavailableView("Couldn't check this plan",systemImage:"exclamationmark.triangle",description:Text(m));case .loaded(let r,let s):List{Section("Your plan"){Text(plan.activityName).font(.title2.bold());LabeledContent(plan.startTime.formatted(date:.abbreviated,time:.shortened),value:"\(plan.durationMinutes) min");Text(plan.location.name).foregroundStyle(.secondary)}Section("What we found"){Text(summary(r))}Section("Your options"){OptionCard(title:"Keep original plan",assessment:r.original,reduction:nil,selected:keepOriginal){keepOriginal=true;selected=nil};ForEach(r.alternatives){a in OptionCard(title:change(a),assessment:a.assessment,reduction:a.reductionPercent(for:r.primaryPollutant ?? .pm25),selected:selected?.id==a.id){selected=a;keepOriginal=false}};if r.alternatives.isEmpty{Text("We didn't find a meaningfully lower-exposure option within the flexibility you provided.").foregroundStyle(.secondary)}}Section{Button("Save Event"){save(result:r,series:s)}.buttonStyle(.borderedProminent).frame(maxWidth:.infinity)}Section{DisclosureGroup("How this was estimated",isExpanded:$details){Text("The app compares time-weighted forecast conditions across only the times you allowed. It does not calculate medical risk.");LabeledContent("Source",value:s.source);LabeledContent("Retrieved",value:s.fetchedAt.formatted())}}}}}.navigationTitle("Exposure").navigationBarTitleDisplayMode(.inline).task{await model.analyze(plan:plan)}}
 func summary(_ r:CounterfactualResult)->String{guard let a=r.bestMeaningful,let p=r.primaryPollutant,let v=a.reductionPercent(for:p)else{return "Forecast conditions are similar across the times you allowed."};return "Fine particle pollution is expected to be lower around \(a.assessment.start.formatted(date:.omitted,time:.shortened)), with about \(Int(v.rounded()))% lower modeled exposure than your original plan."}
 func change(_ a:Alternative)->String{switch a.change{case .timeShift(let m):return m>0 ? "Start \(m) minutes later":"Start \(-m) minutes earlier"}}
 func save(result:CounterfactualResult,series:EnvironmentalTimeSeries){let a=keepOriginal ? result.original:selected?.assessment ?? result.original;let reduction=selected.flatMap{$0.reductionPercent(for:result.primaryPollutant ?? .pm25)};let snap=ExposureSnapshot(analyzedAt:Date(),source:series.source,sourceUpdatedAt:series.fetchedAt,originalStart:plan.startTime,selectedStart:a.start,pm25Mean:a.metric(.pm25)?.meanConcentration,apparentTemperatureC:a.metric(.heat)?.meanConcentration,reductionPercent:reduction);var selectedPlan=plan; selectedPlan.startTime=a.start; app.events.save(.init(plan:selectedPlan,selectedStart:a.start,selectedRoute:nil,analysis:snap));app.selectedTab = .calendar;dismiss()}
}
struct OptionCard:View{let title:String;let assessment:ExposureAssessment;let reduction:Double?;let selected:Bool;let action:()->Void;var body:some View{Button(action:action){HStack{Image(systemName:selected ? "checkmark.circle.fill":"circle");VStack(alignment:.leading){Text(title).font(.headline);Text("\(assessment.start.formatted(date:.omitted,time:.shortened))–\(assessment.end.formatted(date:.omitted,time:.shortened))");if let reduction{Text("\(Int(reduction.rounded()))% lower modeled fine particle exposure").font(.subheadline).foregroundStyle(.secondary)}}}.contentShape(Rectangle())}.buttonStyle(.plain).padding(.vertical,5)}}
